// setupImpersonationHeaders sets up Impersonate-User and Impersonate-Group headers
type clusterSession struct {
	authContext
	parent    *Forwarder
	creds     *kubeCreds
	tlsConfig *tls.Config
	forwarder *forward.Forwarder
	// kubeAddress is the selected endpoint address for dialing and audit events.
	kubeAddress string
	endpoints   []kubeClusterEndpoint
	selectedEndpoint *kubeClusterEndpoint
	// noAuditEvents is true if this teleport service should leave audit event
	// logging to another service.
	noAuditEvents bool
}

func (s *clusterSession) monitorConn(conn net.Conn, err error) (net.Conn, error) {
	if err != nil {
		return nil, trace.Wrap(err)
	}

	ctx, cancel := context.WithCancel(s.parent.ctx)
	tc, err := srv.NewTrackingReadConn(srv.TrackingReadConnConfig{
		Conn:    conn,
		Clock:   s.parent.cfg.Clock,
		Context: s.parent.cfg.Context,
		Cancel:  cancel,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = srv.StartMonitor(srv.MonitorConfig{
		LockWatcher:           s.parent.cfg.LockWatcher,
		LockTargets:           s.LockTargets(),
		DisconnectExpiredCert: s.disconnectExpiredCert,
		ClientIdleTimeout:     s.clientIdleTimeout,
		Clock:                 s.parent.cfg.Clock,
		Tracker:               tc,
		Conn:                  tc,
		Context:               ctx,
		TeleportUser:          s.User.GetName(),
		ServerID:              s.parent.cfg.ServerID,
		Entry:                 s.parent.log,
		Emitter:               s.parent.cfg.AuthClient,
	})
	if err != nil {
		tc.Close()
		return nil, trace.Wrap(err)
	}
	return tc, nil
}

func (s *clusterSession) Dial(network, addr string) (net.Conn, error) {
	return s.monitorConn(s.dial(context.Background(), network))
}

func (s *clusterSession) DialWithContext(ctx context.Context, network, addr string) (net.Conn, error) {
	return s.monitorConn(s.dial(ctx, network))
}

// selectEndpoint chooses one endpoint for the lifetime of the session, so the
// address used by all requests is the same as the one recorded in audit events.
func (s *clusterSession) selectEndpoint() error {
	if len(s.endpoints) == 0 {
		return trace.BadParameter("no Kubernetes cluster endpoints available")
	}
	if s.selectedEndpoint != nil {
		return nil
	}
	endpoint := s.endpoints[mathrand.Intn(len(s.endpoints))]
	s.selectedEndpoint = &endpoint
	s.kubeAddress = endpoint.addr
	return nil
}

// dial is separated from the monitored dialers to allow endpoint selection to
// be tested without starting a connection monitor.
func (s *clusterSession) dial(ctx context.Context, network string) (net.Conn, error) {
	if err := s.selectEndpoint(); err != nil {
		return nil, trace.Wrap(err)
	}
	return s.teleportCluster.dialEndpoint(ctx, network, *s.selectedEndpoint)
}

func (f *Forwarder) newClusterSession(ctx authContext) (*clusterSession, error) {
	if ctx.kubeCluster == "" {
		return nil, trace.NotFound("kubernetes cluster is not specified")
	}

	sess := &clusterSession{
		parent:      f,
		authContext: ctx,
	}
	if ctx.teleportCluster.isRemote {
		// A leaf cluster is reached through its reverse tunnel.
		sess.endpoints = []kubeClusterEndpoint{{addr: reversetunnel.LocalKubernetes}}
	} else if creds := f.creds[ctx.kubeCluster]; creds != nil {
		// Local kubeconfig credentials take priority over registered services.
		f.log.Debugf("Handling kubernetes session for %v using local credentials.", ctx)
		sess.creds = creds
		sess.endpoints = []kubeClusterEndpoint{{addr: creds.targetAddr}}
		sess.tlsConfig = creds.tlsConfig
	} else {
		endpoints, err := f.kubeClusterEndpoints(ctx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if len(endpoints) == 0 {
			return nil, trace.NotFound("kubernetes cluster %q has no local credentials or registered kube_service endpoints in Teleport cluster %q", ctx.kubeCluster, ctx.teleportCluster.name)
		}
		f.log.WithField("kube_service.endpoints", endpoints).Debugf("Kubernetes session for %v forwarded to kubernetes_service.", ctx)
		sess.endpoints = endpoints
		// The kubernetes_service handles audit logging for these sessions.
		sess.noAuditEvents = true
	}

	if sess.creds == nil {
		var err error
		sess.tlsConfig, err = f.getOrRequestClientCreds(ctx)
		if err != nil {
			f.log.Warningf("Failed to get certificate for %v: %v.", ctx, err)
			return nil, trace.AccessDenied("access denied: failed to authenticate with auth server")
		}
	}
	if err := sess.selectEndpoint(); err != nil {
		return nil, trace.Wrap(err)
	}

	transport := http.RoundTripper(f.newTransport(sess.Dial, sess.tlsConfig))
	if sess.creds != nil {
		// Kubeconfig may add a bearer token for in-cluster or exec credentials.
		var err error
		transport, err = sess.creds.wrapTransport(transport)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}

	var err error
	sess.forwarder, err = forward.New(
		forward.FlushInterval(100*time.Millisecond),
		forward.RoundTripper(transport),
		forward.WebsocketDial(sess.Dial),
		forward.Logger(f.log),
		forward.ErrorHandler(fwdutils.ErrorHandlerFunc(f.formatForwardResponseError)),
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return sess, nil
}

func (f *Forwarder) kubeClusterEndpoints(ctx authContext) ([]kubeClusterEndpoint, error) {
	kubeServices, err := f.cfg.CachingAuthClient.GetKubeServices(f.ctx)
	if err != nil && !trace.IsNotFound(err) {
		return nil, trace.Wrap(err)
	}

	var endpoints []kubeClusterEndpoint
	for _, service := range kubeServices {
		for _, cluster := range service.GetKubernetesClusters() {
			if cluster.Name == ctx.kubeCluster {
				endpoints = append(endpoints, kubeClusterEndpoint{
					addr:     service.GetAddr(),
					serverID: fmt.Sprintf("%s.%s", service.GetName(), ctx.teleportCluster.name),
				})
				break
			}
		}
	}
	return endpoints, nil
}

