		f.cfg.CachingAuthClient = mockAccessPoint{
			kubeServices: []types.Server{
				publicKubeServer,
				reverseTunnelKubeServer,
			},
		}

		sess, err := f.newClusterSession(authCtx)
		require.NoError(t, err)

		_, err = sess.dial(ctx, "tcp")
		require.NoError(t, err)
		require.Equal(t, "tcp", dialedNetwork)
		require.Equal(t, dialedAddr, sess.kubeAddress)
		firstAddr, firstServerID := dialedAddr, dialedServerID
		_, err = sess.dial(ctx, "tcp")
		require.NoError(t, err)
		require.Equal(t, firstAddr, dialedAddr)
		require.Equal(t, firstServerID, dialedServerID)
		require.Equal(t, firstAddr, sess.kubeAddress)

		// The endpoint used to dial will be chosen at random. Make sure we hit one of them.
		switch dialedAddr {
		case publicKubeServer.GetAddr():
			expectServerID := fmt.Sprintf("%v.%v", publicKubeServer.GetName(), authCtx.teleportCluster.name)
